total_products_purchased = GRAPH.CALCULATE(
    total_quantity=SUM(
        order_item.WHERE(
            order_item.customer_order.order_date < '2018-03-17 07:13:53'
        ).CALCULATE(
            # Convert order_quantity to an integer before summing
            quantity_as_int=INT(order_quantity)
        ).quantity_as_int
    )
)

total_products_ordered_before_timestamp = GRAPH.CALCULATE(
    total_amount=SUM(
        TO_NUMBER(
            Customer_Orders.WHERE(
                Customer_Orders.order_date < DATETIME('2018-03-17 07:13:53')
            ).Order_Items.order_quantity
        )
    )
)

